import type { ReactNode } from './react.ts';
// The stub is not generic: items is unknown[], so render's item is unknown.
type ListProps = { items: unknown[]; render: (item: unknown) => ReactNode };
export function List(props: ListProps): ReactNode[] {
  return props.items.map(props.render);
}
export const out = List({ items: [1, 2, 3], render: (n) => 'n=' + n.toFixed(0) });

